{
  "idea_id": "P08",
  "verdict": "kill",
  "tests": [
    { "id": "R001", "result": "pass", "evidence": "No professional-liability or funds-holding obligation is inherent to selling offshore compute capacity to cloud/AI companies; this is an infrastructure business, not a regulated financial/professional activity.", "source_url": null },
    { "id": "T2", "result": "pass", "evidence": "No single revocable third-party platform dependency is described; the model is owning/operating physical vessels, not building on a third-party API.", "source_url": null },
    { "id": "T3", "result": "unknown", "evidence": "The idea requires acquiring/retrofitting vessels and modular data-center hardware, but this is closer to capital infrastructure (T7) than resellable inventory; not enough detail to call T3 specifically, and T7 already kills.", "source_url": null },
    { "id": "T7", "result": "fail", "evidence": "Every real-world comparable requires vessel fleets, offshore power generation, marine engineering, and hundreds of millions in capital: Panthalassa raised $140M then was raising $225M more at a ~$2B valuation to build wave-powered floating data center 'nodes' 85 meters tall (arstechnica.com, techstartups.com); Nautilus Data Technologies needed $100M to complete a single 6MW floating facility (datacenterfrontier.com); MOL/Hitachi and Seatrium require ship conversion, classification society approval (Bureau Veritas), and shipyard-scale engineering. This is a fleet-and-facilities business explicitly beyond a solo operator with AI agents.", "source_url": "https://arstechnica.com/ai/2026/05/silicon-valley-bets-on-floating-ai-data-centers-powered-by-ocean-waves/" }
  ],
  "flags": [
    { "id": "T4", "evidence": "Selling multi-megawatt compute capacity to hyperscale AI/cloud companies requires enterprise procurement cycles, RFPs, and long sales relationships, as seen in MOU-based deals like MOL/Hitachi and Aker BP/Armada.", "obligations": [] },
    { "id": "T6", "evidence": "Vessel conversion, offshore power integration, and classification approval (e.g., Bureau Veritas AiP process for Seatrium) mean many months to years before a paying customer, far beyond 90 days.", "obligations": [] }
  ],
  "competitors": [
    { "name": "Panthalassa", "url": "https://www.muus.com/in-the-news/peter-thiel-backs-1bn-ocean-data-centre-start-up-powered-by-waves", "relationship": "direct", "pricing": null, "evidence": "Wave-powered floating data center fleet, raised $140M then reportedly raising $225M more at ~$2B valuation to build 85m steel structures." },
    { "name": "Nautilus Data Technologies", "url": "https://www.datacenterdynamics.com/en/news/nautilus-data-technologies-launches-first-floating-data-center/", "relationship": "direct", "pricing": null, "evidence": "Operates a floating data center barge in Stockton, CA; needed $100M funding to complete a 6MW facility." },
    { "name": "NetworkOcean", "url": "https://www.networkocean.io/", "relationship": "direct", "pricing": null, "evidence": "Builds floating data center barges and underwater capsules scalable to 200MW+, offers colocation and compute reservation." },
    { "name": "MOL / Hitachi Floating Data Center", "url": "https://www.hitachi.com/en/press/articles/2026/03/0330/", "relationship": "direct", "pricing": null, "evidence": "MOU to convert used ships into floating data centers for AI demand, major shipping and industrial conglomerates involved." },
    { "name": "Seatrium", "url": "https://www.offshore-mag.com/business-briefs/equipment-engineering/news/55394471/seatrium-and-mocean-push-offshore-data-center-concepts-to-meet-rising-ai-demand", "relationship": "direct", "pricing": null, "evidence": "Received Bureau Veritas Approval in Principle for a 30MW floating data center barge concept with modular 'Data-in-a-Box' units." },
    { "name": "Seaforge Inc.", "url": "https://seaforgeusa.com", "relationship": "direct", "pricing": null, "evidence": "Develops offshore data-center vessels with onboard power generation and seawater cooling for compute capacity." }
  ],
